    def test_changed_path_summary_accepts_targeted_generated_diff(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            before_target = root / "before-target"
            after_target = root / "after-target"
            before_generated = before_target / "entry/src/main/ets/generated/GeneratedForm.ets"
            after_generated = after_target / "entry/src/main/ets/generated/GeneratedForm.ets"
            before_manifest = before_target / ".migration/arkui-pages/sample.json"
            after_manifest = after_target / ".migration/arkui-pages/sample.json"
            before_generated.parent.mkdir(parents=True)
            after_generated.parent.mkdir(parents=True)
            before_manifest.parent.mkdir(parents=True)
            after_manifest.parent.mkdir(parents=True)
            before_generated.write_text("TextInput({ text: value })\n", encoding="utf-8")
            after_generated.write_text(
                "Column() {\n"
                "  TextInput({ text: value })\n"
                "  if (error !== '') {\n"
                "    Text(error)\n"
                "  }\n"
                "}\n",
                encoding="utf-8",
            )
            before_manifest.write_text(
                json.dumps(
                    {
                        "schema": "android-to-harmony.arkui-page-manifest.v1",
                        "unresolved": [
                            {
                                "kind": "component_semantics",
                                "reason": "OutlinedTextField supportingText is not safely translated",
                            }
                        ],
                    },
                    indent=2,
                ),
                encoding="utf-8",
            )
            after_manifest.write_text(
                json.dumps(
                    {
                        "schema": "android-to-harmony.arkui-page-manifest.v1",
                        "unresolved": [],
                    },
                    indent=2,
                ),
                encoding="utf-8",
            )
            before_result = root / "before-generate.json"
            after_result = root / "after-generate.json"
            before_result.write_text(
                json.dumps(
                    {
                        "ok": True,
                        "schema": "android-to-harmony.command-result.v1",
                        "target": str(before_target),
                        "output": "entry/src/main/ets/generated/GeneratedForm.ets",
                        "manifest": ".migration/arkui-pages/sample.json",
                    },
                    indent=2,
                ),
                encoding="utf-8",
            )
            after_result.write_text(
                json.dumps(
                    {
                        "ok": True,
                        "schema": "android-to-harmony.command-result.v1",
                        "target": str(after_target),
                        "output": "entry/src/main/ets/generated/GeneratedForm.ets",
                        "manifest": ".migration/arkui-pages/sample.json",
                    },
                    indent=2,
                ),
                encoding="utf-8",
            )
            config = root / "changed-config.json"
            config.write_text(
                json.dumps(
                    {
                        "schema": "android-to-harmony.changed-path-summary-config.v1",
                        "samples": [
                            {
                                "name": "supporting-text",
                                "before_generate_result": str(before_result),
                                "after_generate_result": str(after_result),
                                "checks": [
                                    {
                                        "kind": "generated_substring_added",
                                        "substring": "Text(error)",
                                    },
                                    {
                                        "kind": "manifest_reason_removed",
                                        "contains": "supportingText is not safely translated",
                                    },
                                ],
                            }
                        ],
                    },
                    indent=2,
                ),
                encoding="utf-8",
            )
            output = root / "changed-summary.json"
            result = run_script(
                GENERATE_CHANGED_PATH_SUMMARY,
                "--config",
                str(config),
                "--output",
                str(output),
            )
            self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
            summary = json.loads(output.read_text(encoding="utf-8"))
            self.assertEqual(summary["sample_count"], 1)
            self.assertTrue(summary["samples"][0]["generated_changed"])
            self.assertTrue(summary["samples"][0]["changed_paths_covered"])

