    def test_arkui_page_generator_preserves_simple_state_guarded_text(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
            target = root / "HarmonyFixture"
            contract = root / "contract.json"
            screen = source / "app/src/main/java/example/StateGuardedText.kt"
            screen.parent.mkdir(parents=True)
            screen.write_text(
                """
                package example

                import androidx.compose.foundation.layout.Column
                import androidx.compose.material.Button
                import androidx.compose.material.Text
                import androidx.compose.runtime.Composable
                import androidx.compose.runtime.mutableStateOf
                import androidx.compose.runtime.remember

                @Composable
                fun StateGuardedText() {
                  val hasError = remember { mutableStateOf(false) }
                  Column {
                    if (hasError.value) {
                      Text("Required")
                    }
                    Button(onClick = { hasError.value = !hasError.value }) {
                      Text("Submit")
                    }
                  }
                }
                """,
                encoding="utf-8",
            )
            self.assertEqual(
                run_script(PREPARE, "--source", str(source), "--snapshot", str(snapshot)).returncode,
                0,
            )
            self.assertEqual(
                run_script(ANALYZE, "--snapshot", str(snapshot), "--output", str(contract)).returncode,
                0,
            )
            analyzed = json.loads(contract.read_text(encoding="utf-8"))
            guarded_calls = [
                call
                for call in analyzed["ui"]["semantic_translation_candidates"]["calls"]
                if call["component"] == "Text"
                and call.get("visibility_condition", {}).get("expression") == "hasError.value"
            ]
            self.assertEqual(len(guarded_calls), 1, guarded_calls)
            self.assertEqual(
                run_script(
                    INITIALIZE,
                    "--output",
                    str(target),
                    "--project-name",
                    "HarmonyFixture",
                    "--bundle-name",
                    "com.example.harmonyfixture",
                    "--contract",
                    str(contract),
                ).returncode,
                0,
            )
            generated = run_script(
                GENERATE_ARKUI_PAGE,
                "--contract",
                str(contract),
                "--target",
                str(target),
                "--root-source",
                "app/src/main/java/example/StateGuardedText.kt",
                "--root-composable",
                "StateGuardedText",
            )
            self.assertEqual(generated.returncode, 0, generated.stdout + generated.stderr)
            result = json.loads(generated.stdout)
            manifest = json.loads((target / result["manifest"]).read_text(encoding="utf-8"))
            self.assertFalse(
                any(item["kind"] == "visibility_condition" for item in manifest["unresolved"]),
                manifest["unresolved"],
            )
            self.assertFalse(
                any(
                    item["kind"] == "component_semantics"
                    and item.get("component") == "AnimatedVisibility"
                    and "platform/default/slot reconciliation" in item["reason"]
                    for item in manifest["unresolved"]
                ),
                manifest["unresolved"],
            )
            generated_source = (target / result["output"]).read_text(encoding="utf-8")
            self.assertIn("if (this.stateHasError", generated_source)
            self.assertIn("Text('Required')", generated_source)
            self.assertIn(".onClick(() => { this.stateHasError", generated_source)

    def test_arkui_page_generator_emits_form_validation_click_with_root_callbacks(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
            target = root / "HarmonyFixture"
            contract = root / "contract.json"
            screen = source / "app/src/main/java/example/LoginForm.kt"
            screen.parent.mkdir(parents=True)
            screen.write_text(
                """
                package example

                import androidx.compose.foundation.layout.Column
                import androidx.compose.material.Button
                import androidx.compose.material.Text
                import androidx.compose.material.TextButton
                import androidx.compose.material.TextField
                import androidx.compose.runtime.Composable
                import androidx.compose.runtime.mutableStateOf
                import androidx.compose.runtime.remember

                @Composable
                fun LoginForm(
                  loginPress: (username: String, password: String) -> Unit,
                  registerPress: () -> Unit,
                ) {
                  val username = remember { mutableStateOf("") }
                  val emailErrorState = remember { mutableStateOf(false) }
                  val password = remember { mutableStateOf("") }
                  val passwordErrorState = remember { mutableStateOf(false) }
                  Column {
                    TextField(
                      value = username.value,
                      onValueChange = {
                        if (emailErrorState.value) { emailErrorState.value = false }
                        username.value = it
                      },
                      label = { Text("Username") },
                    )
                    if (emailErrorState.value) {
                      Text("Username is required")
                    }
                    TextField(
                      value = password.value,
                      onValueChange = {
                        if (passwordErrorState.value) { passwordErrorState.value = false }
                        password.value = it
                      },
                      label = { Text("Password") },
                    )
                    if (passwordErrorState.value) {
                      Text("Password is required")
                    }
                    Button(onClick = {
                      when {
                        username.value.isEmpty() -> { emailErrorState.value = true }
                        password.value.isEmpty() -> { passwordErrorState.value = true }
                        else -> loginPress(username.value, password.value)
                      }
                    }) {
                      Text("Login")
                    }
                    TextButton(onClick = registerPress) {
                      Text("Register")
                    }
                  }
                }
                """,
                encoding="utf-8",
            )
            self.assertEqual(
                run_script(PREPARE, "--source", str(source), "--snapshot", str(snapshot)).returncode,
                0,
            )
