    def test_arkui_page_generator_emits_safe_modifier_primitives(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
            target = root / "HarmonyFixture"
            contract = root / "contract.json"
            screen = source / "app/src/main/java/example/SafeModifiers.kt"
            screen.parent.mkdir(parents=True)
            screen.write_text(
                """
                package example

                import androidx.compose.foundation.clickable
                import androidx.compose.foundation.layout.Box
                import androidx.compose.foundation.layout.heightIn
                import androidx.compose.foundation.layout.IntrinsicSize
                import androidx.compose.foundation.layout.matchParentSize
                import androidx.compose.foundation.layout.offset
                import androidx.compose.foundation.layout.requiredHeight
                import androidx.compose.foundation.layout.requiredWidthIn
                import androidx.compose.foundation.layout.size
                import androidx.compose.foundation.layout.sizeIn
                import androidx.compose.foundation.layout.wrapContentHeight
                import androidx.compose.foundation.layout.wrapContentSize
                import androidx.compose.foundation.layout.widthIn
                import androidx.compose.foundation.shape.CircleShape
                import androidx.compose.foundation.shape.RoundedCornerShape
                import androidx.compose.runtime.Composable
                import androidx.compose.ui.Alignment
                import androidx.compose.ui.Modifier
                import androidx.compose.ui.draw.alpha
                import androidx.compose.ui.draw.clip
                import androidx.compose.ui.draw.rotate
                import androidx.compose.ui.graphics.Color
                import androidx.compose.ui.unit.Dp
                import androidx.compose.ui.unit.dp

                @Composable
                fun SafeModifierScreen() {
                  SafeModifierChild(onClick = {})
                }

                @Composable
                fun SafeModifierChild(
                  onClick: () -> Unit,
                  disabled: Boolean = false,
                  bgColor: Color = Color.Red,
                  logoHeight: Dp = 24.dp,
                  maxHeight: Dp = 80.dp,
                ) {
                  val animatedAlpha = animateFloatAsState(targetValue = if (disabled) 0f else 1f)
                  Box(
                    modifier = Modifier
                      .wrapContentSize()
                      .size(width = logoHeight * 1.65f, height = logoHeight)
                      .aspectRatio(1.5f)
                      .matchParentSize()
                      .height(IntrinsicSize.Max)
                      .requiredHeight(56.dp)
                      .widthIn(min = 24.dp, max = 120.dp)
                      .requiredWidthIn(max = LocalConfiguration.current.screenWidthDp.dp - 100.dp)
                      .heightIn(min = 16.dp, max = 64.dp)
                      .sizeIn(minWidth = 32.dp, minHeight = 48.dp, maxWidth = 180.dp, maxHeight = 240.dp)
                      .offset(x = (-56).dp, y = 8.dp)
                      .offset(x = maxHeight / 4, y = -maxHeight / 4)
                      .align(Alignment.BottomEnd)
                      .rotate(-45F)
                      .alpha(0.5f)
                      .alpha(if (disabled) 0.6f else 1f)
                      .alpha(animatedAlpha.value)
                      .background(bgColor, RoundedCornerShape(12.dp))
                      .clip(RoundedCornerShape(16.dp))
                      .clip(RoundedCornerShape(40))
                      .clip(CircleShape)
                      .clickable(onClick = onClick)
                      .then(Modifier.wrapContentHeight(unbounded = true, align = Alignment.Top))
                  )
                  Box(modifier = Modifier.clickable { onClick() })
                }
                """,
                encoding="utf-8",
            )
            self.assertEqual(
                run_script(PREPARE, "--source", str(source), "--snapshot", str(snapshot)).returncode,
                0,
            )
            self.assertEqual(
                run_script(ANALYZE, "--snapshot", str(snapshot), "--output", str(contract)).returncode,
                0,
            )
            self.assertEqual(
                run_script(
                    INITIALIZE,
                    "--output",
                    str(target),
                    "--project-name",
                    "HarmonyFixture",
                    "--bundle-name",
                    "com.example.harmonyfixture",
                    "--contract",
                    str(contract),
                ).returncode,
                0,
            )
            generated = run_script(
                GENERATE_ARKUI_PAGE,
                "--contract",
                str(contract),
                "--target",
                str(target),
                "--root-source",
                "app/src/main/java/example/SafeModifiers.kt",
                "--root-composable",
                "SafeModifierScreen",
            )
            self.assertEqual(generated.returncode, 0, generated.stdout + generated.stderr)
            result = json.loads(generated.stdout)
            manifest = json.loads((target / result["manifest"]).read_text(encoding="utf-8"))
            self.assertFalse(
                any(item["kind"] == "modifier" for item in manifest["unresolved"]),
                manifest["unresolved"],
            )
            generated_source = (target / result["output"]).read_text(encoding="utf-8")
            self.assertIn(".width('100%')", generated_source)
            self.assertIn(".height('100%')", generated_source)
            self.assertIn(".width(logoHeight * 1.65)", generated_source)
            self.assertIn(".height(logoHeight)", generated_source)
            self.assertIn(".aspectRatio(1.5)", generated_source)
            self.assertIn(".height(56)", generated_source)
            self.assertIn(".constraintSize({ minWidth: 24, maxWidth: 120 })", generated_source)
            self.assertIn(".constraintSize({ maxWidth: 'calc(100% - 100vp)' })", generated_source)
            self.assertIn(".constraintSize({ minHeight: 16, maxHeight: 64 })", generated_source)
            self.assertIn(".constraintSize({ minWidth: 32, minHeight: 48, maxWidth: 180, maxHeight: 240 })", generated_source)
            self.assertIn(".translate({ x: -56, y: 8 })", generated_source)
            self.assertIn(".translate({ x: maxHeight / 4, y: -maxHeight / 4 })", generated_source)
            self.assertIn(".align(Alignment.BottomEnd)", generated_source)
            self.assertIn(".rotate({ angle: -45 })", generated_source)
            self.assertIn(".opacity(0.5)", generated_source)
            self.assertIn(".opacity((disabled ? 0.6 : 1))", generated_source)
            self.assertIn(".opacity((disabled ? 0 : 1))", generated_source)
            self.assertIn(".backgroundColor(bgColor)", generated_source)
            self.assertIn(".borderRadius(12)", generated_source)
            self.assertIn(".borderRadius(16)", generated_source)
            self.assertIn(".borderRadius('40%')", generated_source)
            self.assertIn(".borderRadius('50%')", generated_source)
            self.assertIn(".onClick(() => { onClick() })", generated_source)

