    def test_arkui_page_generator_expands_expression_body_optional_spacers(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
            target = root / "HarmonyFixture"
            contract = root / "contract.json"
            screen = source / "app/src/main/java/example/ExpressionBodySpacer.kt"
            screen.parent.mkdir(parents=True)
            screen.write_text(
                """
                package example

                import androidx.compose.foundation.layout.Column
                import androidx.compose.foundation.layout.Spacer
                import androidx.compose.foundation.layout.height
                import androidx.compose.foundation.layout.width
                import androidx.compose.runtime.Composable
                import androidx.compose.ui.Modifier
                import androidx.compose.ui.unit.Dp
                import androidx.compose.ui.unit.dp

                @Composable
                fun Host() {
                  Column {
                    VerticalSpace(15.dp)
                    HorizontalSpace()
                  }
                }

                @Composable
                fun VerticalSpace(height: Dp = Dp.Unspecified) = CustomSpacer(height = height)

                @Composable
                fun HorizontalSpace(width: Dp = Dp.Unspecified) = CustomSpacer(width = width)

                @Composable
                fun CustomSpacer(
                  height: Dp = Dp.Unspecified,
                  width: Dp = Dp.Unspecified
                ) {
                  Spacer(
                    modifier = Modifier
                      .let { if (height != Dp.Unspecified) it.height(height) else it }
                      .let { if (width != Dp.Unspecified) it.width(width) else it }
                  )
                }
                """,
                encoding="utf-8",
            )
            self.assertEqual(
                run_script(PREPARE, "--source", str(source), "--snapshot", str(snapshot)).returncode,
                0,
            )
            self.assertEqual(
                run_script(ANALYZE, "--snapshot", str(snapshot), "--output", str(contract)).returncode,
                0,
            )
            analyzed = json.loads(contract.read_text(encoding="utf-8"))
            closures = analyzed["ui"]["custom_composable_call_graph"]["transitive_closures"]
            host_closure = next(
                item
                for item in closures
                if item["root"] == {
                    "source": "app/src/main/java/example/ExpressionBodySpacer.kt",
                    "composable": "Host",
                }
            )
            self.assertEqual(host_closure["reached_definition_count"], 4)
            self.assertEqual(
                run_script(
                    INITIALIZE,
                    "--output",
                    str(target),
                    "--project-name",
                    "HarmonyFixture",
                    "--bundle-name",
                    "com.example.harmonyfixture",
                    "--contract",
                    str(contract),
                ).returncode,
                0,
            )
            generated = run_script(
                GENERATE_ARKUI_PAGE,
                "--contract",
                str(contract),
                "--target",
                str(target),
                "--root-source",
                "app/src/main/java/example/ExpressionBodySpacer.kt",
                "--root-composable",
                "Host",
            )
            self.assertEqual(generated.returncode, 0, generated.stdout + generated.stderr)
            result = json.loads(generated.stdout)
            manifest = json.loads((target / result["manifest"]).read_text(encoding="utf-8"))
            self.assertFalse(
                any(item["kind"] in {"invocation_argument", "modifier", "project_component"} for item in manifest["unresolved"]),
                manifest["unresolved"],
            )
            generated_source = (target / result["output"]).read_text(encoding="utf-8")
            self.assertIn("private VerticalSpace_", generated_source)
            self.assertIn("this.CustomSpacer_", generated_source)
            self.assertIn("if (height !== undefined)", generated_source)
            self.assertIn(".height(height)", generated_source)
            self.assertIn("if (width !== undefined)", generated_source)
            self.assertIn(".width(width)", generated_source)
            self.assertNotIn("Dp.Unspecified", generated_source)

