            screen.parent.mkdir(parents=True)
            screen.write_text(
                """
                package example

                import androidx.compose.foundation.layout.Arrangement
                import androidx.compose.foundation.layout.Box
                import androidx.compose.foundation.layout.Column
                import androidx.compose.foundation.layout.fillMaxSize
                import androidx.compose.foundation.layout.Row
                import androidx.compose.material.Text
                import androidx.compose.runtime.Composable
                import androidx.compose.ui.Alignment
                import androidx.compose.ui.Modifier
                import androidx.compose.ui.unit.Dp
                import androidx.compose.ui.unit.dp

                @Composable
                fun AlignmentHost() {
                  Box(contentAlignment = Alignment.TopCenter) {
                    Text("Top")
                  }
                  Box(contentAlignment = Alignment.BottomCenter) {
                    Text("Bottom")
                  }
                  Box(modifier = Modifier.fillMaxSize()) {
                    Text("BottomAligned", modifier = Modifier.align(Alignment.BottomCenter))
                  }
                  Column(verticalArrangement = Arrangement.SpaceBetween) {
                    Text("A")
                    Text("B")
                  }
                  Row(horizontalArrangement = Arrangement.spacedBy(16.dp)) {
                    Text("C")
                    Text("D")
                  }
                  Row(horizontalArrangement = Arrangement.spacedBy(20.dp, Alignment.CenterHorizontally)) {
                    Text("G")
                    Text("H")
                  }
                  Row(horizontalArrangement = Arrangement.SpaceEvenly) {
                    Text("I")
                    Text("J")
                  }
                  SpacedColumn(gap = 12.dp)
                  AlignedRow()
                }

                @Composable
                fun SpacedColumn(gap: Dp) {
                  Column(verticalArrangement = Arrangement.spacedBy(gap)) {
                    Text("E")
                    Text("F")
                  }
                }

                @Composable
                fun AlignedRow(verticalAlignment: Alignment.Vertical = Alignment.CenterVertically) {
                  Row(verticalAlignment = verticalAlignment) {
                    Text("K")
                  }
                }
                """,
                encoding="utf-8",
            )
