    def test_arkui_page_generator_maps_padding_values_parameters(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
            target = root / "HarmonyFixture"
            contract = root / "contract.json"
            screen = source / "app/src/main/java/example/PaddingValuesScreen.kt"
            screen.parent.mkdir(parents=True)
            screen.write_text(
                """
                package example

                import androidx.compose.foundation.layout.Box
                import androidx.compose.foundation.layout.PaddingValues
                import androidx.compose.foundation.layout.padding
                import androidx.compose.material3.Scaffold
                import androidx.compose.runtime.Composable
                import androidx.compose.ui.Modifier
                import androidx.compose.ui.unit.dp

                @Composable
                fun PaddingValuesHost() {
                  PaddingPanel(paddingValues = PaddingValues(horizontal = 12.dp, vertical = 8.dp))
                  ScaffoldPanel()
                  NamedScaffoldPanel()
                }

                @Composable
                fun PaddingPanel(paddingValues: PaddingValues = PaddingValues()) {
                  Box(modifier = Modifier.padding(paddingValues))
                  Box(
                    modifier = Modifier.padding(
                      top = paddingValues.calculateTopPadding() + 16.dp,
                      bottom = paddingValues.calculateBottomPadding() + 40.dp,
                      start = 24.dp,
                      end = 24.dp,
                    )
                  )
                }

                @Composable
                fun ScaffoldPanel() {
                  Scaffold { pv ->
                    Box(
                      modifier = Modifier.padding(
                        top = pv.calculateTopPadding() + 16.dp,
                        bottom = pv.calculateBottomPadding() + 40.dp,
                        start = 24.dp,
                        end = 24.dp,
                      )
                    )
                  }
                }

                @Composable
                fun NamedScaffoldPanel() {
                  Scaffold { paddingValues ->
                    Box(modifier = Modifier.padding(paddingValues))
                  }
                }
                """,
                encoding="utf-8",
            )
            self.assertEqual(
                run_script(PREPARE, "--source", str(source), "--snapshot", str(snapshot)).returncode,
                0,
            )
            self.assertEqual(
                run_script(ANALYZE, "--snapshot", str(snapshot), "--output", str(contract)).returncode,
                0,
            )
            self.assertEqual(
                run_script(
                    INITIALIZE,
                    "--output",
                    str(target),
                    "--project-name",
                    "HarmonyFixture",
                    "--bundle-name",
                    "com.example.harmonyfixture",
                    "--contract",
                    str(contract),
                ).returncode,
                0,
            )
            generated = run_script(
                GENERATE_ARKUI_PAGE,
                "--contract",
                str(contract),
                "--target",
                str(target),
                "--root-source",
                "app/src/main/java/example/PaddingValuesScreen.kt",
                "--root-composable",
                "PaddingValuesHost",
            )
            self.assertEqual(generated.returncode, 0, generated.stdout + generated.stderr)
            result = json.loads(generated.stdout)
            manifest = json.loads((target / result["manifest"]).read_text(encoding="utf-8"))
            self.assertFalse(
                any(item["kind"] in {"parameter_type", "invocation_argument", "modifier"} for item in manifest["unresolved"]),
                manifest["unresolved"],
            )
            self.assertFalse(
                any(
                    item["kind"] == "component_semantics"
                    and item.get("component") == "Scaffold"
                    for item in manifest["unresolved"]
                ),
                manifest["unresolved"],
            )
            self.assertTrue(
                any(item["kind"] == "scaffold_padding" for item in manifest["unresolved"]),
                manifest["unresolved"],
            )
            generated_source = (target / result["output"]).read_text(encoding="utf-8")
            self.assertIn("paddingValues: Padding", generated_source)
            self.assertIn("this.PaddingPanel_", generated_source)
            self.assertIn("{ left: 12, right: 12, top: 8, bottom: 8 }", generated_source)
            self.assertIn(".padding(paddingValues)", generated_source)
            self.assertIn(
                ".padding({ left: 24, right: 24, top: paddingValues.top + 16, bottom: paddingValues.bottom + 40 })",
                generated_source,
            )
            self.assertIn(
                ".padding({ left: 24, right: 24, top: 0 + 16, bottom: 0 + 40 })",
                generated_source,
            )
            self.assertIn(
                ".padding({ left: 0, right: 0, top: 0, bottom: 0 })",
                generated_source,
            )

