    def test_contract_preserves_for_each_dropdown_item_context(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
            contract = root / "contract.json"
            screen = source / "app/src/main/java/example/DropdownContext.kt"
            screen.parent.mkdir(parents=True)
            screen.write_text(
                """
                package example

                import androidx.compose.material3.DropdownMenuItem
                import androidx.compose.material3.ExposedDropdownMenuBox
                import androidx.compose.material3.OutlinedTextField
                import androidx.compose.runtime.Composable
                import androidx.compose.runtime.mutableStateOf
                import androidx.compose.runtime.remember
                import androidx.compose.ui.Modifier
                import androidx.compose.material3.menuAnchor

                enum class Currency(val label: String) {
                  USD("US Dollar"),
                  EUR("Euro")
                }

                @Composable
                fun DropdownContextHost() {
                  val options = listOf("Salary", "Bonus")
                  var expanded by remember { mutableStateOf(false) }
                  var selectedSource by remember { mutableStateOf("Salary") }
                  var selectedCurrency by remember { mutableStateOf(Currency.USD) }
                  ExposedDropdownMenuBox(
                    expanded = expanded,
                    onExpandedChange = { expanded = !expanded }
                  ) {
                    OutlinedTextField(
                      value = selectedSource,
                      onValueChange = {},
                      readOnly = true,
                      modifier = Modifier.menuAnchor()
                    )
                    options.forEach { source ->
                      DropdownMenuItem(
                        text = { Text(source) },
                        onClick = { selectedSource = source; expanded = false }
                      )
                    }
                    Currency.entries.forEach { currency ->
                      DropdownMenuItem(
                        text = { Text(currency.label) },
                        onClick = { selectedCurrency = currency; expanded = false }
                      )
                    }
                  }
                }
                """,
                encoding="utf-8",
            )
            self.assertEqual(
                run_script(PREPARE, "--source", str(source), "--snapshot", str(snapshot)).returncode,
                0,
            )
            analyzed = run_script(
                ANALYZE,
                "--snapshot",
                str(snapshot),
                "--output",
                str(contract),
            )
            self.assertEqual(analyzed.returncode, 0, analyzed.stdout + analyzed.stderr)
            calls = json.loads(contract.read_text(encoding="utf-8"))["ui"][
                "semantic_translation_candidates"
            ]["calls"]
            string_item = next(
                call
                for call in calls
                if call["component"] == "DropdownMenuItem"
                and call["semantic_arguments"]["text"]["expression"] == "{ Text(source) }"
            )
            enum_item = next(
                call
                for call in calls
                if call["component"] == "DropdownMenuItem"
                and call["semantic_arguments"]["text"]["expression"] == "{ Text(currency.label) }"
            )
            self.assertEqual(
                string_item["list_item_context"],
                {"collection": "options", "item_parameter": "source"},
            )
            self.assertEqual(
                enum_item["list_item_context"],
                {"collection": "Currency.entries", "item_parameter": "currency"},
            )

