    def test_contract_uses_explicit_imports_to_guard_primitive_mapping(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
            contract = root / "contract.json"
            compose_screen = source / "app/src/main/java/example/ComposeCard.kt"
            foreign_screen = source / "app/src/main/java/example/ForeignCard.kt"
            constraint_screen = source / "app/src/main/java/example/ConstraintScreen.kt"
            compose_screen.parent.mkdir(parents=True)
            compose_screen.write_text(
                """
                package example

                import androidx.compose.material3.Card

                @Composable
                fun ComposeCardScreen() {
                  Card { Text("Compose") }
                }
                """,
                encoding="utf-8",
            )
            foreign_screen.write_text(
                """
                package example

                import com.brand.widgets.Card

                @Composable
                fun ForeignCardScreen() {
                  Card { Text("Foreign") }
                }
                """,
                encoding="utf-8",
            )
            constraint_screen.write_text(
                """
                package example

                import androidx.constraintlayout.compose.ConstraintLayout

                @Composable
                fun ConstraintScreen() {
                  ConstraintLayout { Text("Constrained") }
                }
                """,
                encoding="utf-8",
            )
            prepared = run_script(
                PREPARE,
                "--source",
                str(source),
                "--snapshot",
                str(snapshot),
            )
            self.assertEqual(prepared.returncode, 0, prepared.stdout)
            analyzed = run_script(
                ANALYZE,
                "--snapshot",
                str(snapshot),
                "--output",
                str(contract),
            )
            self.assertEqual(analyzed.returncode, 0, analyzed.stdout + analyzed.stderr)

            ui = json.loads(contract.read_text(encoding="utf-8"))["ui"]
            card_calls = [
                call
                for call in ui["semantic_translation_candidates"]["calls"]
                if call["component"] == "Card"
            ]
            compose_call = next(
                call for call in card_calls if call["composable"] == "ComposeCardScreen"
            )
            foreign_call = next(
                call for call in card_calls if call["composable"] == "ForeignCardScreen"
            )
            self.assertEqual(
                compose_call["primitive_mapping_id"],
                "compose.material.card",
            )
            self.assertEqual(
                compose_call["primitive_mapping_resolution"],
                {
                    "status": "explicit_compose_import",
                    "imported_symbol": "androidx.compose.material3.Card",
                },
            )
            self.assertNotIn("primitive_mapping_id", foreign_call)
            self.assertEqual(
                foreign_call["primitive_mapping_resolution"],
                {
                    "status": "rejected_explicit_non_compose_import",
                    "imported_symbol": "com.brand.widgets.Card",
                },
            )
            constraint_call = next(
                call
                for call in ui["semantic_translation_candidates"]["calls"]
                if call["component"] == "ConstraintLayout"
            )
            self.assertEqual(
                constraint_call["primitive_mapping_id"],
                "compose.constraint-layout",
            )
            self.assertEqual(
                constraint_call["primitive_mapping_resolution"],
                {
                    "status": "explicit_compose_import",
                    "imported_symbol": "androidx.constraintlayout.compose.ConstraintLayout",
                },
            )

