    def test_arkui_page_generator_binds_custom_calendar_state_picker_and_apply_callback(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
