    def test_contract_preserves_resolved_custom_composable_call_graph(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
            contract = root / "contract.json"
            screen = source / "app/src/main/java/example/home/HomeScreen.kt"
