            components.parent.mkdir(parents=True)
            screen.write_text(
                """
                package example.home

                import example.home.components.AutoTrackingCard
                import example.home.components.HomeAppBar

                @Composable
                fun HomeScreen(user: User) {
                  Column() {
                    HomeAppBar(
                      user = user,
                      selectedDateRange = DateRange.ThisWeek,
                      onClick = { openDateRange() }
                    )
                    AutoTrackingCard(
                      isEnable = false,
                      onEnableClick = { openTracking() }
                    )
                    Account(name = "not a composable")
                  }
                }
                """,
                encoding="utf-8",
            )
            components.write_text(
                """
                package example.home.components

                @Composable
                fun HomeAppBar(
                  user: User,
                  selectedDateRange: DateRange,
                  onClick: () -> Unit
                ) {
                  Row() { Text(user.name) }
                }

                @Composable
                fun AutoTrackingCard(
                  isEnable: Boolean,
                  onEnableClick: () -> Unit
                ) {
                  Surface() { Text("Auto Tracking") }
                }
                """,
                encoding="utf-8",
            )
            prepared = run_script(
                PREPARE,
                "--source",
                str(source),
                "--snapshot",
                str(snapshot),
            )
            self.assertEqual(prepared.returncode, 0, prepared.stdout)
            analyzed = run_script(
                ANALYZE,
                "--snapshot",
                str(snapshot),
                "--output",
                str(contract),
            )
            self.assertEqual(
                analyzed.returncode,
                0,
                analyzed.stdout + analyzed.stderr,
            )

            ui = json.loads(contract.read_text(encoding="utf-8"))["ui"]
            calls = ui["semantic_translation_candidates"]["calls"]
            home_calls = [
                call for call in calls if call["composable"] == "HomeScreen"
            ]
            components_by_name = {call["component"]: call for call in home_calls}
            self.assertIn("HomeAppBar", components_by_name, calls)
            self.assertIn("AutoTrackingCard", components_by_name)
            self.assertNotIn("Account", components_by_name)

            app_bar = components_by_name["HomeAppBar"]
            column = components_by_name["Column"]
            self.assertEqual(app_bar["parent_call_id"], column["call_id"])
            self.assertEqual(
                app_bar["custom_composable"]["definitions"],
                [
                    {
                        "source": "app/src/main/java/example/home/components/HomeComponents.kt",
                        "composable": "HomeAppBar",
                    }
                ],
            )
            self.assertEqual(
                [item["name"] for item in app_bar["custom_composable"]["arguments"]],
                ["user", "selectedDateRange", "onClick"],
            )
            self.assertEqual(
                app_bar["custom_composable"]["arguments"][1]["expression"],
                "DateRange.ThisWeek",
            )
            app_bar_text = next(
                call
                for call in calls
                if call["composable"] == "HomeAppBar"
                and call["component"] == "Text"
            )
            self.assertEqual(
                app_bar_text["positional_arguments"],
                [
                    {
                        "expression": "user.name",
                        "dimension_resources": [],
                        "dimensions": [],
                    }
                ],
            )
            tracking_text = next(
                call
                for call in calls
                if call["composable"] == "AutoTrackingCard"
                and call["component"] == "Text"
            )
            self.assertEqual(
                tracking_text["positional_arguments"][0]["expression"],
                '"Auto Tracking"',
            )

            graph = ui["custom_composable_call_graph"]
            self.assertEqual(graph["status"], "candidate_requires_review")
            self.assertFalse(graph["authoritative"])
            self.assertEqual(graph["edge_count"], 2)
            self.assertEqual(
                [(edge["caller"]["composable"], edge["callee"]["composable"])
                 for edge in graph["edges"]],
                [
                    ("HomeScreen", "AutoTrackingCard"),
                    ("HomeScreen", "HomeAppBar"),
                ],
            )
            home_closure = next(
                closure
                for closure in graph["transitive_closures"]
                if closure["root"]["composable"] == "HomeScreen"
            )
            self.assertEqual(
                {
                    item["composable"]
                    for item in home_closure["reached_definitions"]
                },
                {"HomeScreen", "HomeAppBar", "AutoTrackingCard"},
            )
            self.assertEqual(home_closure["project_component_call_count"], 2)
            self.assertEqual(home_closure["primitive_call_count"], 5)
            self.assertEqual(home_closure["mapped_primitive_call_count"], 5)
            self.assertEqual(home_closure["unmapped_primitive_components"], [])
            self.assertFalse(home_closure["cycle_detected"])

