    def test_contract_extracts_compose_theme_tokens_and_bindings(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
            contract = root / "contract.json"
            theme = source / "app/src/main/java/example/theme/AppTheme.kt"
            theme.parent.mkdir(parents=True)
            theme.write_text(
                """
                package example.theme

                val BrandPrimary = Color(0xFF112233)
                val BrandFont = FontFamily(
                  Font(R.font.brand_regular, FontWeight.Normal)
                )
                val SpaceSmall = 8.dp

                private val LightColors = lightColorScheme(
                  primary = BrandPrimary,
                  onPrimary = Color.White,
                  background = Color.White
                  /* Material defaults kept as source comments:
                  background = Color.Black,
                  onPrimary = Color.Black,
                  */
                )
                private val DarkColors = darkColorScheme(
                  primary = Color.Black,
                  onPrimary = Color.White
                )
                val AppTypography = Typography(
                  bodyLarge = TextStyle(
                    fontFamily = BrandFont,
                    fontWeight = FontWeight.Medium,
                    fontSize = 16.sp,
                    lineHeight = 24.sp,
                    letterSpacing = 0.5.sp
                  )
                )
                val AppShapes = Shapes(
                  small = RoundedCornerShape(4.dp),
                  medium = RoundedCornerShape(12.dp),
                  large = CutCornerShape(0.dp)
                )

                @Composable
                fun AppTheme(
                  darkTheme: Boolean,
                  content: @Composable () -> Unit
                ) {
                  val colors = if (darkTheme) {
                    DarkColors
                  } else {
                    LightColors
                  }
                  MaterialTheme(
                    colorScheme = colors,
                    typography = AppTypography,
                    shapes = AppShapes,
                    content = content
                  )
                }
                """,
                encoding="utf-8",
            )
            prepared = run_script(
                PREPARE,
                "--source",
                str(source),
                "--snapshot",
                str(snapshot),
            )
            self.assertEqual(prepared.returncode, 0, prepared.stdout)
            analyzed = run_script(
                ANALYZE,
                "--snapshot",
                str(snapshot),
                "--output",
                str(contract),
            )
            self.assertEqual(analyzed.returncode, 0, analyzed.stdout + analyzed.stderr)

            inventory = json.loads(contract.read_text(encoding="utf-8"))["ui"][
                "compose_theme_token_inventory"
            ]
            self.assertFalse(inventory["authoritative"])
            tokens = {item["name"]: item for item in inventory["tokens"]}
            self.assertEqual(tokens["BrandPrimary"]["kind"], "color")
            self.assertEqual(tokens["BrandPrimary"]["argb_hex"], "#FF112233")
            self.assertEqual(tokens["BrandFont"]["kind"], "font_family")
            self.assertEqual(
                tokens["BrandFont"]["font_resource_keys"],
                ["brand_regular"],
            )
            self.assertEqual(tokens["SpaceSmall"]["kind"], "dimension")
            self.assertEqual(
                tokens["SpaceSmall"]["dimensions"],
                [{"value": "8", "unit": "dp"}],
            )

            schemes = {item["name"]: item for item in inventory["color_schemes"]}
            self.assertEqual(schemes["LightColors"]["variant"], "light")
            self.assertEqual(
                schemes["LightColors"]["roles"]["primary"]["expression"],
                "BrandPrimary",
            )
            self.assertEqual(
                schemes["LightColors"]["roles"]["primary"]["resolved_token"],
                {
                    "status": "resolved_unique",
                    "name": "BrandPrimary",
                    "kind": "color",
                    "argb_hex": "#FF112233",
                },
            )
            self.assertEqual(
                schemes["LightColors"]["roles"]["background"]["expression"],
                "Color.White",
            )
            self.assertEqual(schemes["DarkColors"]["variant"], "dark")

            typography = inventory["typography_sets"][0]
            self.assertEqual(typography["name"], "AppTypography")
            body_large = typography["styles"]["bodyLarge"]
            self.assertEqual(
                body_large["properties"]["fontFamily"]["expression"],
                "BrandFont",
            )
            self.assertEqual(
                body_large["properties"]["fontFamily"]["resolved_token"],
                {
                    "status": "resolved_unique",
                    "name": "BrandFont",
                    "kind": "font_family",
                    "font_resource_keys": ["brand_regular"],
                },
            )
            self.assertEqual(
                body_large["properties"]["fontSize"]["dimensions"],
                [{"value": "16", "unit": "sp"}],
            )

            shapes = inventory["shape_sets"][0]
            self.assertEqual(shapes["name"], "AppShapes")
            self.assertEqual(
                shapes["roles"]["medium"]["dimensions"],
                [{"value": "12", "unit": "dp"}],
            )

            application = inventory["theme_applications"][0]
            self.assertEqual(
                application["arguments"]["colorScheme"]["expression"],
                "colors",
            )
            self.assertEqual(
                application["conditional_bindings"],
                [
                    {
                        "name": "colors",
                        "condition": "darkTheme",
                        "when_true": "DarkColors",
                        "when_false": "LightColors",
                    }
                ],
            )

    def test_arkui_page_generator_maps_material_theme_extension_colors(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
            target = root / "HarmonyFixture"
            contract = root / "contract.json"
            screen = source / "app/src/main/java/example/ExtendedTheme.kt"
            screen.parent.mkdir(parents=True)
            screen.write_text(
                """
                package example

                import androidx.compose.foundation.border
                import androidx.compose.foundation.layout.Box
                import androidx.compose.foundation.shape.RoundedCornerShape
                import androidx.compose.material3.MaterialTheme
                import androidx.compose.material3.Text
                import androidx.compose.runtime.Composable
                import androidx.compose.runtime.staticCompositionLocalOf
                import androidx.compose.ui.Modifier
                import androidx.compose.ui.graphics.Color
                import androidx.compose.ui.unit.dp

                val Dark40 = Color(0xFF333333)
                val Light60 = Color(0xFFEAEAEA)
                val Violet40 = Color(0xFF7F3DFF)

                data class ExtendedColors(
                  val iconColor: Color = Dark40,
                  val primaryBorder: Color = Dark40,
                  val bottomNavBg: Color = Violet40.copy(alpha = 0.1f),
                  val missingColor: Color = Color.Unspecified
                )

                val LightExtendedColors = ExtendedColors(iconColor = Dark40)
                val DarkExtendedColors = ExtendedColors(iconColor = Light60)
                val LocalExtendedColors = staticCompositionLocalOf { LightExtendedColors }

                val MaterialTheme.extendedColors: ExtendedColors
                  @Composable get() = LocalExtendedColors.current

                @Composable
                fun ExtendedThemeScreen(disabled: Boolean = false) {
                  Text("Icon", color = MaterialTheme.extendedColors.iconColor)
                  Box(
                    modifier = Modifier.border(
                      1.dp,
                      MaterialTheme.extendedColors.primaryBorder.copy(alpha = if (disabled) 0.6f else 1f),
                      RoundedCornerShape(16.dp)
                    )
                  )
                }
                """,
                encoding="utf-8",
            )
            self.assertEqual(
                run_script(PREPARE, "--source", str(source), "--snapshot", str(snapshot)).returncode,
                0,
            )
            analyzed = run_script(ANALYZE, "--snapshot", str(snapshot), "--output", str(contract))
            self.assertEqual(analyzed.returncode, 0, analyzed.stdout + analyzed.stderr)
            inventory = json.loads(contract.read_text(encoding="utf-8"))["ui"][
                "compose_theme_token_inventory"
            ]
            extended_sets = {item["name"]: item for item in inventory["extended_color_sets"]}
            self.assertEqual(
                extended_sets["LightExtendedColors"]["roles"]["iconColor"]["resolved_token"],
                {
                    "status": "resolved_unique",
                    "name": "Dark40",
                    "kind": "color",
                    "argb_hex": "#FF333333",
                },
            )
            self.assertEqual(extended_sets["DarkExtendedColors"]["variant"], "dark")

            initialized = run_script(
                INITIALIZE,
                "--output",
                str(target),
                "--project-name",
                "HarmonyFixture",
                "--bundle-name",
                "com.example.harmonyfixture",
                "--contract",
                str(contract),
            )
            self.assertEqual(initialized.returncode, 0, initialized.stdout)
            generated_theme = run_script(
                GENERATE_THEME_RESOURCES,
                "--contract",
                str(contract),
                "--target",
                str(target),
            )
            self.assertEqual(generated_theme.returncode, 0, generated_theme.stdout)
            base_colors = json.loads(
                (target / "entry/src/main/resources/base/element/color.json").read_text(
                    encoding="utf-8"
                )
            )["color"]
            dark_colors = json.loads(
                (target / "entry/src/main/resources/dark/element/color.json").read_text(
                    encoding="utf-8"
                )
            )["color"]
            self.assertIn(
                {"name": "compose_extended_color_icon_color", "value": "#FF333333"},
                base_colors,
            )
            self.assertIn(
                {"name": "compose_extended_color_bottom_nav_bg", "value": "#1A7F3DFF"},
                base_colors,
            )
            self.assertIn(
                {"name": "compose_extended_color_icon_color", "value": "#FFEAEAEA"},
                dark_colors,
            )

            generated = run_script(
                GENERATE_ARKUI_PAGE,
                "--contract",
                str(contract),
                "--target",
                str(target),
                "--root-source",
                "app/src/main/java/example/ExtendedTheme.kt",
                "--root-composable",
                "ExtendedThemeScreen",
            )
            self.assertEqual(generated.returncode, 0, generated.stdout + generated.stderr)
            result = json.loads(generated.stdout)
            manifest = json.loads((target / result["manifest"]).read_text(encoding="utf-8"))
            self.assertFalse(
                any(
                    item["kind"] == "typography"
                    and item["reason"] == "color override is not safely translated"
                    for item in manifest["unresolved"]
                ),
                manifest["unresolved"],
            )
            generated_source = (target / result["output"]).read_text(encoding="utf-8")
            self.assertIn(
                ".fontColor($r('app.color.compose_extended_color_icon_color'))",
                generated_source,
            )
            self.assertIn(".border({ width: 1, color: (disabled ? '#99333333' : '#FF333333') })", generated_source)
            self.assertIn(".borderRadius(16)", generated_source)

