    def test_contract_keeps_function_parameter_after_line_comment_in_parameter_list(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
            contract = root / "contract.json"
            screen = source / "app/src/main/java/example/CommentedParams.kt"
            screen.parent.mkdir(parents=True)
            screen.write_text(
                """
                package example

                import androidx.compose.runtime.Composable

                data class UiField(val value: String)

                @Composable
                fun FormField(
                  title: String,
                  // TODO rename
                  uiField: UiField,
                  onValueChange: (String) -> Unit
                ) {
                }
                """,
                encoding="utf-8",
            )
            self.assertEqual(
                run_script(PREPARE, "--source", str(source), "--snapshot", str(snapshot)).returncode,
                0,
            )
            analyzed = run_script(ANALYZE, "--snapshot", str(snapshot), "--output", str(contract))
            self.assertEqual(analyzed.returncode, 0, analyzed.stdout + analyzed.stderr)
            composables = json.loads(contract.read_text(encoding="utf-8"))["ui"]["composables"]
            form_field = next(item for item in composables if item["name"] == "FormField")
            parameters = {item["name"]: item["type"] for item in form_field["parameters"]}
            self.assertEqual(parameters["uiField"], "UiField")
            self.assertEqual(parameters["onValueChange"], "(String) -> Unit")

