    def test_skill_tree_manifest_is_path_independent_and_detects_changes(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            trees = [root / "installed", root / "development"]
            outputs = [root / "installed.json", root / "development.json"]
            for tree in trees:
                (tree / "nested").mkdir(parents=True)
                (tree / "plugin.json").write_text('{"version":"1"}\n', encoding="utf-8")
                (tree / "nested/tool.py").write_text("print('ok')\n", encoding="utf-8")

            manifests = []
            for tree, output in zip(trees, outputs):
                hashed = run_script(
                    HASH_SKILL_TREE,
                    "--root",
                    str(tree),
                    "--output",
                    str(output),
                )
                self.assertEqual(hashed.returncode, 0, hashed.stdout)
                manifests.append(json.loads(output.read_text(encoding="utf-8")))

            self.assertEqual(
                manifests[0]["tree_sha256"],
                manifests[1]["tree_sha256"],
            )
            self.assertEqual(
                [entry["path"] for entry in manifests[0]["files"]],
                ["nested/tool.py", "plugin.json"],
            )
            self.assertEqual(manifests[0]["file_count"], 2)

            (trees[1] / "nested/tool.py").write_text(
                "print('changed')\n",
                encoding="utf-8",
            )
            changed_output = root / "changed.json"
            changed = run_script(
                HASH_SKILL_TREE,
                "--root",
                str(trees[1]),
                "--output",
                str(changed_output),
            )
            self.assertEqual(changed.returncode, 0, changed.stdout)
            self.assertNotEqual(
                manifests[0]["tree_sha256"],
                json.loads(changed_output.read_text(encoding="utf-8"))[
                    "tree_sha256"
                ],
            )

            refused = run_script(
                HASH_SKILL_TREE,
                "--root",
                str(trees[0]),
                "--output",
                str(trees[0] / "self-referential.json"),
            )
            self.assertNotEqual(refused.returncode, 0)
            self.assertIn("outside the hashed root", refused.stdout)

    def test_skill_tree_manifest_excludes_generated_python_bytecode(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            trees = [root / "installed", root / "development"]
            outputs = [root / "installed.json", root / "development.json"]
            for index, tree in enumerate(trees):
                (tree / "scripts/__pycache__").mkdir(parents=True)
                (tree / "scripts/tool.py").write_text(
                    "print('same source')\n",
                    encoding="utf-8",
                )
                (tree / "scripts/__pycache__/tool.cpython-314.pyc").write_bytes(
                    f"path-dependent-bytecode-{index}".encode("utf-8")
                )

            manifests = []
            for tree, output in zip(trees, outputs):
                hashed = run_script(
                    HASH_SKILL_TREE,
                    "--root",
                    str(tree),
                    "--output",
                    str(output),
                )
                self.assertEqual(hashed.returncode, 0, hashed.stdout)
                manifests.append(json.loads(output.read_text(encoding="utf-8")))

            self.assertEqual(
                manifests[0]["tree_sha256"],
                manifests[1]["tree_sha256"],
            )
            self.assertEqual(
                [entry["path"] for entry in manifests[0]["files"]],
                ["scripts/tool.py"],
            )

    def test_copies_only_manifest_approved_asset_with_matching_hash(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
            target = root / "HarmonyFixture"
            destination = (
                target
                / "entry/src/main/resources/base/media/copied_app_icon.png"
            )
            (source / "app/src/main/res/drawable").mkdir(parents=True)
            image_bytes = b"\x89PNG\r\n\x1a\n" + bytes(range(64))
            asset = source / "app/src/main/res/drawable/app_icon.png"
            asset.write_bytes(image_bytes)

            prepared = run_script(
                PREPARE,
                "--source",
                str(source),
                "--snapshot",
                str(snapshot),
            )
            self.assertEqual(prepared.returncode, 0, prepared.stdout)
            initialized = run_script(
                INITIALIZE,
                "--output",
                str(target),
                "--project-name",
                "HarmonyFixture",
                "--bundle-name",
                "com.example.harmonyfixture",
            )
            self.assertEqual(initialized.returncode, 0, initialized.stdout)
            copied = run_script(
                COPY_ASSET,
                "--manifest",
                str(snapshot / ".android-to-harmony-safe.json"),
                "--asset-path",
                "app/src/main/res/drawable/app_icon.png",
                "--target",
                str(target),
                "--destination",
                str(destination),
            )
            self.assertEqual(copied.returncode, 0, copied.stdout)
            self.assertEqual(destination.read_bytes(), image_bytes)
            self.assertNotIn(image_bytes.hex(), copied.stdout)
            copied_again = run_script(
                COPY_ASSET,
                "--manifest",
                str(snapshot / ".android-to-harmony-safe.json"),
                "--asset-path",
                "app/src/main/res/drawable/app_icon.png",
                "--target",
                str(target),
                "--destination",
                str(destination),
            )
            self.assertEqual(copied_again.returncode, 0, copied_again.stdout)
            self.assertFalse(json.loads(copied_again.stdout)["changed"])

            target_manifest = target / ".migration/target-source-manifest.json"
            hashed = run_script(
                HASH_TARGET,
                "--target",
                str(target),
                "--output",
                str(target_manifest),
            )
            self.assertEqual(hashed.returncode, 0, hashed.stdout)
            manifest_text = target_manifest.read_text(encoding="utf-8")
            manifest_paths = {
                entry["path"]
                for entry in json.loads(manifest_text)["files"]
            }
            self.assertIn(".migration/assets.json", manifest_paths)
            self.assertIn(
                destination.relative_to(target).as_posix(),
                manifest_paths,
            )
            self.assertNotIn(base64.b64encode(image_bytes).decode(), manifest_text)
            self.assertNotIn(image_bytes.hex(), manifest_text)

            unrelated_destination = (
                target / "entry/src/main/resources/base/media/unrelated.png"
            )
            unrelated_destination.write_bytes(b"not-owned-by-the-copier")
            overwrite_refused = run_script(
                COPY_ASSET,
                "--manifest",
                str(snapshot / ".android-to-harmony-safe.json"),
                "--asset-path",
                "app/src/main/res/drawable/app_icon.png",
                "--target",
                str(target),
                "--destination",
                str(unrelated_destination),
                "--force",
            )
            self.assertNotEqual(overwrite_refused.returncode, 0)
            self.assertEqual(
                unrelated_destination.read_bytes(),
                b"not-owned-by-the-copier",
            )
            self.assertIn(
                "unowned destination",
                json.loads(overwrite_refused.stdout)["error"],
            )

            asset.write_bytes(image_bytes + b"changed")
            refused = run_script(
                COPY_ASSET,
                "--manifest",
                str(snapshot / ".android-to-harmony-safe.json"),
                "--asset-path",
                "app/src/main/res/drawable/app_icon.png",
                "--target",
                str(target),
                "--destination",
                str(
                    target
                    / "entry/src/main/resources/base/media/changed.png"
                ),
            )
            self.assertNotEqual(refused.returncode, 0)
            self.assertIn("changed", json.loads(refused.stdout)["error"])

