            destination = (
                target
                / "entry/src/main/resources/rawfile/fonts/brand_regular.ttf"
            )
            font.parent.mkdir(parents=True)
            font_bytes = b"opaque-font-fixture\x00\x01\x02"
            font.write_bytes(font_bytes)

            prepared = run_script(
                PREPARE,
                "--source",
                str(source),
                "--snapshot",
                str(snapshot),
            )
            self.assertEqual(prepared.returncode, 0, prepared.stdout)
            manifest = json.loads(
                (snapshot / ".android-to-harmony-safe.json").read_text(
                    encoding="utf-8"
                )
            )
            self.assertEqual(
                [asset["path"] for asset in manifest["local_only_assets"]],
                ["app/src/main/res/font/brand_regular.ttf"],
            )
            initialized = run_script(
                INITIALIZE,
                "--output",
                str(target),
                "--project-name",
                "HarmonyFixture",
                "--bundle-name",
                "com.example.harmonyfixture",
            )
