            copied = run_script(
                COPY_ASSET,
                "--manifest",
                str(snapshot / ".android-to-harmony-safe.json"),
                "--asset-path",
                "app/src/main/res/font/brand_regular.ttf",
                "--target",
                str(target),
                "--destination",
                str(destination),
            )
            self.assertEqual(copied.returncode, 0, copied.stdout)
            self.assertEqual(destination.read_bytes(), font_bytes)
            self.assertNotIn(font_bytes.hex(), copied.stdout)

            target_manifest = target / ".migration/target-source-manifest.json"
