    def test_target_source_manifest_force_is_owned_by_generator_and_target(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            targets = (root / "target-a", root / "target-b")
            outputs: list[Path] = []
            for target in targets:
                initialized = run_script(
                    INITIALIZE,
                    "--output",
                    str(target),
                    "--project-name",
                    "HarmonyFixture",
                    "--bundle-name",
                    "com.example.harmonyfixture",
                )
                self.assertEqual(initialized.returncode, 0, initialized.stdout)
                output = target / ".migration/target-source-manifest.json"
                hashed = run_script(
                    HASH_TARGET,
                    "--target",
                    str(target),
                    "--output",
                    str(output),
                )
                self.assertEqual(hashed.returncode, 0, hashed.stdout)
                outputs.append(output)

            manifest_a = json.loads(outputs[0].read_text(encoding="utf-8"))
            self.assertEqual(
                manifest_a["generator"],
                "migrate-android-compose-to-harmony",
            )
            self.assertEqual(
                manifest_a["local_target_root"],
                str(targets[0].resolve()),
            )
            outputs[1].write_text(
                json.dumps(manifest_a, ensure_ascii=False, indent=2) + "\n",
                encoding="utf-8",
            )

            wrong_target = run_script(
                HASH_TARGET,
                "--target",
                str(targets[1]),
                "--output",
                str(outputs[1]),
                "--force",
            )
            self.assertNotEqual(wrong_target.returncode, 0)
            self.assertIn(
                "different local target",
                json.loads(wrong_target.stdout)["error"],
            )

            manifest_a["local_target_root"] = str(targets[1].resolve())
            manifest_a["generator"] = "unrelated-generator"
            outputs[1].write_text(
                json.dumps(manifest_a, ensure_ascii=False, indent=2) + "\n",
                encoding="utf-8",
            )
            wrong_generator = run_script(
                HASH_TARGET,
                "--target",
                str(targets[1]),
                "--output",
                str(outputs[1]),
                "--force",
            )
            self.assertNotEqual(wrong_generator.returncode, 0)
            self.assertIn(
                "unowned target source manifest",
                json.loads(wrong_generator.stdout)["error"],
            )

