            source.mkdir()
            (source / "Gallery.kt").write_text(
                '''
                package example

                import androidx.compose.foundation.Image
                import androidx.compose.runtime.Composable
                import example.widgets.RemoteImage

                @Composable
                fun Gallery() {
                  Image(painter = painter, contentDescription = null)
                  RemoteImage()
                  LocalImage()
                  CacheImage()
                  // CommentImage()
                  val documentation = """StringImage()"""
                }

                fun CacheImage() = Unit
                ''',
                encoding="utf-8",
            )
            (source / "LocalImage.kt").write_text(
                """
                package example

                import androidx.compose.runtime.Composable

                @Composable
                fun LocalImage() = Unit
                """,
                encoding="utf-8",
            )

