            analyzed = run_script(
                ANALYZE,
                "--snapshot",
                str(snapshot),
                "--output",
                str(contract),
            )
            self.assertEqual(analyzed.returncode, 0, analyzed.stdout)
            payload = json.loads(contract.read_text(encoding="utf-8"))
