    def test_analyzer_resolves_symbolic_compose_routes(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
            contract = root / "contract.json"
            source.mkdir()
            (source / "TodoNavigation.kt").write_text(
                """
                private object TodoScreens {
                  const val TASKS_SCREEN = "tasks"
                  const val STATISTICS_SCREEN = "statistics"
                  const val TASK_DETAIL_SCREEN = "task"
                  const val ADD_EDIT_TASK_SCREEN = "addEditTask"
                }
                object TodoDestinationsArgs {
                  const val USER_MESSAGE_ARG = "userMessage"
                  const val TASK_ID_ARG = "taskId"
                  const val TITLE_ARG = "title"
                }
                object TodoDestinations {
                  const val TASKS_ROUTE =
                    "$TASKS_SCREEN?$USER_MESSAGE_ARG={$USER_MESSAGE_ARG}"
                  const val STATISTICS_ROUTE = STATISTICS_SCREEN
                  const val TASK_DETAIL_ROUTE = "$TASK_DETAIL_SCREEN/{$TASK_ID_ARG}"
                  const val ADD_EDIT_TASK_ROUTE =
                    "$ADD_EDIT_TASK_SCREEN/{$TITLE_ARG}?$TASK_ID_ARG={$TASK_ID_ARG}"
                }
                """,
                encoding="utf-8",
            )
            (source / "TodoNavGraph.kt").write_text(
                """
                fun NavGraphBuilder.todoGraph() {
                  composable(TodoDestinations.TASKS_ROUTE) {}
                  composable(TodoDestinations.STATISTICS_ROUTE) {}
                  composable(route = TodoDestinations.ADD_EDIT_TASK_ROUTE) {}
                  composable(TodoDestinations.TASK_DETAIL_ROUTE) {}
                }
                """,
                encoding="utf-8",
            )

            prepared = run_script(
                PREPARE,
                "--source",
                str(source),
                "--snapshot",
                str(snapshot),
            )
            self.assertEqual(prepared.returncode, 0, prepared.stdout)
            analyzed = run_script(
                ANALYZE,
                "--snapshot",
                str(snapshot),
                "--output",
                str(contract),
            )
            self.assertEqual(analyzed.returncode, 0, analyzed.stdout)
            routes = json.loads(contract.read_text(encoding="utf-8"))["ui"][
                "routes"
            ]

            self.assertEqual(
                {route["route"] for route in routes},
                {
                    "tasks?userMessage={userMessage}",
                    "statistics",
                    "addEditTask/{title}?taskId={taskId}",
                    "task/{taskId}",
                },
            )
            self.assertTrue(
                all(route["kind"] == "symbolic" for route in routes)
            )
            self.assertTrue(
                all(route["detector"] == "regex-v2" for route in routes)
            )

