    def test_generate_migration_backlog_rejects_non_object_json(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            contract = root / "contract.json"
            backlog = root / "backlog.json"
            contract.write_text('["not", "a", "contract"]\n', encoding="utf-8")

            generated = run_script(
                GENERATE_BACKLOG,
                "--contract",
                str(contract),
                "--output",
                str(backlog),
            )
            self.assertNotEqual(generated.returncode, 0)
            self.assertFalse(backlog.exists())
            payload = json.loads(generated.stdout)
            self.assertFalse(payload["ok"])
            self.assertIn("JSON object", payload["error"])

    def test_generate_migration_backlog_rejects_wrong_contract_identity_fields(
        self,
    ) -> None:
        fixtures = [
            (
                "wrong-schema",
                {
                    "schema": "not-a-contract",
                    "generator": "migrate-android-compose-to-harmony",
                    "inventory_quality": "candidate",
                    "inventory": {},
                },
                "schema",
            ),
            (
                "missing-generator",
                {
                    "schema": "android-to-harmony.migration-contract.v1",
                    "inventory_quality": "candidate",
                    "inventory": {},
                },
                "generator",
            ),
            (
                "wrong-generator",
                {
                    "schema": "android-to-harmony.migration-contract.v1",
                    "generator": "other-tool",
                    "inventory_quality": "candidate",
                    "inventory": {},
                },
                "generator",
            ),
            (
                "wrong-inventory-quality",
                {
                    "schema": "android-to-harmony.migration-contract.v1",
                    "generator": "migrate-android-compose-to-harmony",
                    "inventory_quality": "authoritative",
                    "inventory": {},
                },
                "inventory_quality",
            ),
            (
                "missing-inventory-quality",
                {
                    "schema": "android-to-harmony.migration-contract.v1",
                    "generator": "migrate-android-compose-to-harmony",
                    "inventory": {},
                },
                "inventory_quality",
            ),
        ]
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            for name, fixture, expected_field in fixtures:
                contract = root / f"{name}.json"
                backlog = root / f"{name}.backlog.json"
                contract.write_text(json.dumps(fixture), encoding="utf-8")

                generated = run_script(
                    GENERATE_BACKLOG,
                    "--contract",
                    str(contract),
                    "--output",
                    str(backlog),
                )
                self.assertNotEqual(generated.returncode, 0, name)
                self.assertFalse(backlog.exists(), name)
                payload = json.loads(generated.stdout)
                self.assertFalse(payload["ok"], name)
                self.assertIn(expected_field, payload["error"], name)

    def test_analyzer_resolves_routes_from_custom_composable_wrappers(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
            contract = root / "contract.json"
            source.mkdir()
            (source / "AppNavigation.kt").write_text(
                """
                object MainDestinations {
                  const val HOME_ROUTE = "home"
                }

                fun NavGraphBuilder.appGraph() {
                  composableWithCompositionLocal(
                    route = MainDestinations.HOME_ROUTE
                  ) {}
                }
                """,
                encoding="utf-8",
            )
            prepared = run_script(
                PREPARE,
                "--source",
                str(source),
                "--snapshot",
                str(snapshot),
            )
            self.assertEqual(prepared.returncode, 0, prepared.stdout)
            analyzed = run_script(
                ANALYZE,
                "--snapshot",
                str(snapshot),
                "--output",
                str(contract),
            )
            self.assertEqual(analyzed.returncode, 0, analyzed.stdout)
            routes = json.loads(contract.read_text(encoding="utf-8"))["ui"][
                "routes"
            ]

            self.assertEqual(
                [(route["route"], route["symbol"]) for route in routes],
                [("home", "MainDestinations.HOME_ROUTE")],
            )

    def test_analyzer_resolves_concatenated_symbolic_route_expressions(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
            contract = root / "contract.json"
            source.mkdir()
            (source / "DetailNavigation.kt").write_text(
                """
                object MainDestinations {
                  const val DETAIL_ROUTE = "snack"
                  const val ITEM_ID = "snackId"
                  const val ORIGIN = "origin"
                }

                fun NavGraphBuilder.appGraph() {
                  composableWithCompositionLocal(
                    "${MainDestinations.DETAIL_ROUTE}/" +
                      "{${MainDestinations.ITEM_ID}}" +
                      "?origin={${MainDestinations.ORIGIN}}"
                  ) {}
                }
                """,
                encoding="utf-8",
            )
            prepared = run_script(
                PREPARE,
                "--source",
                str(source),
                "--snapshot",
                str(snapshot),
            )
            self.assertEqual(prepared.returncode, 0, prepared.stdout)
            analyzed = run_script(
                ANALYZE,
                "--snapshot",
                str(snapshot),
                "--output",
                str(contract),
            )
            self.assertEqual(analyzed.returncode, 0, analyzed.stdout)
