    def test_analyzer_resolves_routes_from_sealed_object_simple_names(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
            contract = root / "contract.json"
            source.mkdir()
            (source / "NavDestinations.kt").write_text(
                """
                sealed class NavDestinations {
                  object Onboarding: NavDestinations()
                  object Login: NavDestinations()

                  object RootGraph: NavDestinations() {
                    object Home : NavDestinations()
                    object CardDetails: NavDestinations()
                  }

                  val route: String
                    get() = this::class.java.simpleName
                }
                """,
                encoding="utf-8",
            )
            (source / "AppNavHost.kt").write_text(
                """
                fun NavGraphBuilder.appGraph() {
                  composable(NavDestinations.Onboarding.route) {}
                  composable(route = NavDestinations.Login.route) {}
                  navigation(
                    startDestination = NavDestinations.RootGraph.Home.route,
                    route = NavDestinations.RootGraph.route
                  ) {
                    composable(NavDestinations.RootGraph.Home.route) {}
                    composable(
                      "${NavDestinations.RootGraph.CardDetails.route}/{cardId}"
                    ) {}
                  }
                }
                """,
                encoding="utf-8",
            )
            prepared = run_script(
                PREPARE,
                "--source",
                str(source),
                "--snapshot",
                str(snapshot),
            )
            self.assertEqual(prepared.returncode, 0, prepared.stdout)
            analyzed = run_script(
                ANALYZE,
                "--snapshot",
                str(snapshot),
                "--output",
                str(contract),
            )
            self.assertEqual(analyzed.returncode, 0, analyzed.stdout)
            routes = json.loads(contract.read_text(encoding="utf-8"))["ui"][
                "routes"
            ]

            self.assertEqual(
                {(route["route"], route.get("symbol")) for route in routes},
                {
                    ("Onboarding", "NavDestinations.Onboarding.route"),
                    ("Login", "NavDestinations.Login.route"),
                    ("RootGraph", "NavDestinations.RootGraph.route"),
                    ("Home", "NavDestinations.RootGraph.Home.route"),
                    ("CardDetails/{cardId}", None),
                },
            )

