    def test_snapshot_blocks_concatenated_base64_decode_payload(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
            source.mkdir()
            encoded = base64.b64encode(
                b"\x89PNG\r\n\x1a\n" + bytes(range(256)) * 2
            ).decode("ascii")
            fragments = [
                encoded[index : index + 80]
                for index in range(0, len(encoded), 80)
            ]
            expression = " +\n".join(
                f'                  "{fragment}"'
                for fragment in fragments
            )
            (source / "Embedded.kt").write_text(
                "val bitmap = Base64.decode(\n"
                f"{expression},\n"
                "                  Base64.DEFAULT)\n",
                encoding="utf-8",
            )

            prepared = run_script(
                PREPARE,
                "--source",
                str(source),
                "--snapshot",
                str(snapshot),
            )
            self.assertEqual(prepared.returncode, 0, prepared.stdout)
            manifest = json.loads(
                (snapshot / ".android-to-harmony-safe.json").read_text(
                    encoding="utf-8"
                )
            )
            self.assertEqual(manifest["blocked_file_count"], 1)
            self.assertEqual(
                manifest["blocked_files"][0]["reason"],
                "embedded_image_payload",
            )
            self.assertFalse((snapshot / "Embedded.kt").exists())
            self.assertNotIn(encoded, prepared.stdout)

