    def test_analyzer_refuses_unowned_overwrite_and_protected_output(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "android"
            snapshot = root / "snapshot"
            source.mkdir()
            (source / "Safe.kt").write_text(
                "const val safe = true\n",
                encoding="utf-8",
            )
            prepared = run_script(
                PREPARE,
                "--source",
                str(source),
                "--snapshot",
                str(snapshot),
            )
            self.assertEqual(prepared.returncode, 0, prepared.stdout)

            existing = root / "existing.json"
            existing.write_text('{"keep":true}\n', encoding="utf-8")
            refused = run_script(
                ANALYZE,
                "--snapshot",
                str(snapshot),
                "--output",
                str(existing),
                "--force",
            )
            self.assertNotEqual(refused.returncode, 0)
            self.assertEqual(
                existing.read_text(encoding="utf-8"),
                '{"keep":true}\n',
            )

            owned = root / "owned.json"
            first = run_script(
                ANALYZE,
                "--snapshot",
                str(snapshot),
                "--output",
                str(owned),
            )
            self.assertEqual(first.returncode, 0, first.stdout)
            second = run_script(
                ANALYZE,
                "--snapshot",
                str(snapshot),
                "--output",
                str(owned),
                "--force",
            )
            self.assertEqual(second.returncode, 0, second.stdout)
            owned.write_text(
                owned.read_text(encoding="utf-8") + "\n",
                encoding="utf-8",
            )
            before = owned.read_text(encoding="utf-8")
            tampered = run_script(
                ANALYZE,
                "--snapshot",
                str(snapshot),
                "--output",
                str(owned),
                "--force",
            )
            self.assertNotEqual(tampered.returncode, 0)
            self.assertEqual(owned.read_text(encoding="utf-8"), before)
            self.assertIn(
                "matching owner",
                json.loads(tampered.stdout)["error"],
            )

            protected = run_script(
                ANALYZE,
                "--snapshot",
                str(snapshot),
                "--output",
                str(snapshot / "contract.json"),
            )
            self.assertNotEqual(protected.returncode, 0)
            self.assertIn(
                "separate",
                json.loads(protected.stdout)["error"],
            )

