            self.assertEqual(
                nodes["control:profilescreen:outlinedtextfield"]["gate_profile"],
                "stateless-control",
            )
            self.assertEqual(
                nodes["page:profilescreen"]["gate_profile"],
                "page",
            )
            self.assertEqual(
                nodes["platform:camera-permission"]["gate_profile"],
                "platform",
            )
            self.assertEqual(
                nodes["network:profileapi"]["gate_profile"],
                "network",
            )
            self.assertEqual(
                nodes["storage:profiledatabase"]["gate_profile"],
                "storage",
            )
            self.assertEqual(
                nodes["business:profileviewmodel"]["gate_profile"],
                "business",
            )
            self.assertEqual(
                nodes["control:profilescreen:datepicker"]["parent_id"],
                "page:profilescreen",
            )
