    def test_capability_graph_builder_uses_source_semantics_and_emits_review_queue(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "source"
            snapshot = root / "snapshot"
            contract_payload = capability_contract_fixture(source, snapshot)
            contract_payload["inventory"]["files_by_layer"]["source"].extend(
                [
                    "app/src/main/java/example/navigation/RouteNames.kt",
                    "app/src/main/java/example/security/CryptoUtils.kt",
                    "app/src/main/java/example/utils/DateUtils.kt",
                    "app/src/main/java/example/misc/AmbiguousThing.kt",
                ]
            )
            contract = root / "contract.json"
            registry = root / "gate-registry.json"
            output = root / "graph.json"
            fact_packs = root / "fact-packs"
            review_queue = root / "review-queue.json"
            write_json(contract, contract_payload)
            write_json(registry, gate_registry_fixture())

            files = {
                "app/src/main/java/example/navigation/RouteNames.kt": """
                    package example.navigation

                    import androidx.navigation.NavHostController

                    sealed interface RouteNames {
                        data object Home : RouteNames
                        data object Detail : RouteNames
                    }
                """,
                "app/src/main/java/example/security/CryptoUtils.kt": """
                    package example.security

                    import javax.crypto.Cipher
                    import androidx.biometric.BiometricPrompt

                    class CryptoUtils {
                        fun buildCipher(prompt: BiometricPrompt): Cipher? = null
                    }
                """,
                "app/src/main/java/example/utils/DateUtils.kt": """
                    package example.utils

                    import java.time.LocalDate
                    import java.time.format.DateTimeFormatter

                    object DateUtils {
                        fun dueDateLabel(date: LocalDate): String =
                            date.format(DateTimeFormatter.ISO_DATE)
                    }
                """,
                "app/src/main/java/example/misc/AmbiguousThing.kt": """
                    package example.misc

                    class AmbiguousThing
                """,
            }
            for relative, contents in files.items():
                source_file = source / relative
                snapshot_file = snapshot / relative
                source_file.parent.mkdir(parents=True, exist_ok=True)
                snapshot_file.parent.mkdir(parents=True, exist_ok=True)
                source_file.write_text(contents.strip() + "\n", encoding="utf-8")
                snapshot_file.write_text(contents.strip() + "\n", encoding="utf-8")

            built = run_script(
                BUILD_CAPABILITY_GRAPH,
                "--contract",
                str(contract),
                "--gate-registry",
                str(registry),
                "--fact-pack-dir",
                str(fact_packs),
                "--output",
                str(output),
            )
            self.assertEqual(built.returncode, 0, built.stdout + built.stderr)

            payload = json.loads(output.read_text(encoding="utf-8"))
            queue_payload = json.loads(review_queue.read_text(encoding="utf-8"))
            primary_owner_by_source: dict[str, dict[str, object]] = {}
            for node in payload["nodes"]:
                for source_path in node.get("primary_source_files", []):
                    primary_owner_by_source[source_path] = node

            route_owner = primary_owner_by_source[
                "app/src/main/java/example/navigation/RouteNames.kt"
            ]
            self.assertEqual(route_owner["layer"], "page")
            self.assertEqual(route_owner["classification"]["confidence"], "high")
            self.assertEqual(
                route_owner["classification"]["primary_rule"],
                "semantic_navigation",
            )

            crypto_owner = primary_owner_by_source[
                "app/src/main/java/example/security/CryptoUtils.kt"
            ]
            self.assertEqual(crypto_owner["layer"], "platform")
            self.assertEqual(
                crypto_owner["classification"]["primary_rule"],
                "semantic_platform_security",
            )

            date_owner = primary_owner_by_source[
                "app/src/main/java/example/utils/DateUtils.kt"
            ]
            self.assertEqual(date_owner["layer"], "business")
            self.assertEqual(
                date_owner["classification"]["primary_rule"],
                "semantic_business_formatting",
            )

            ambiguous_owner = primary_owner_by_source[
                "app/src/main/java/example/misc/AmbiguousThing.kt"
            ]
            self.assertEqual(ambiguous_owner["layer"], "unclassified")
            self.assertEqual(ambiguous_owner["classification"]["confidence"], "low")
            self.assertEqual(
                payload["coverage"]["unclassified_source_files"],
                ["app/src/main/java/example/misc/AmbiguousThing.kt"],
            )
            self.assertEqual(
                queue_payload["unclassified_source_files"],
                payload["coverage"]["unclassified_source_files"],
            )
            self.assertEqual(queue_payload["entry_count"], 1)
            self.assertEqual(
                queue_payload["entries"][0]["source_path"],
                "app/src/main/java/example/misc/AmbiguousThing.kt",
            )
            self.assertIn("candidate_layers", queue_payload["entries"][0])
            self.assertIn("supporting_evidence", queue_payload["entries"][0])
            self.assertIn("blocking_parent_gates", queue_payload["entries"][0])

