    def test_execution_plan_builder_rejects_unknown_and_cyclic_dependencies(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            contract, _, contract_sha = self._write_batch2_contract(root)
            graph = root / "graph.json"
            plan = root / "execution-plan.json"
            graph_payload, _ = self._batch2_graph_fixture(
                root,
                contract_sha256=contract_sha,
                include_produced_contract=True,
            )
            for node in graph_payload["nodes"]:
                if node["id"] == "business:settingsviewmodel":
                    node["produced_contract_ids"] = ["typed:settings"]
                if node["id"] == "business:profileviewmodel":
                    node["required_contract_ids"] = ["typed:settings"]
            graph_payload["resolved_edges"].append(
                {
                    "edge_id": "edge-profile-consumes-settings-contract",
                    "kind": "runtime_call",
                    "from_node_id": "business:profileviewmodel",
                    "to_node_id": "business:settingsviewmodel",
                    "source_path": "app/src/main/java/example/ui/ProfileViewModel.kt",
                    "source_symbol": "ProfileViewModel",
                    "evidence": {"kind": "call", "detail": "typed:settings"},
                    "consumed_by_planner": "provenance_only",
                }
            )
            write_json(graph, graph_payload)
            gate_report = self._write_batch1_gate_report(root, graph_path=graph, graph_payload=graph_payload)
            planned = run_script(
                BUILD_EXECUTION_PLAN,
                "--contract", str(contract),
                "--graph", str(graph),
                "--gate-report", str(gate_report),
                "--output", str(plan),
            )
            self.assertNotEqual(planned.returncode, 0)
            self.assertIn("cycle", json.loads(planned.stdout)["error"])

    def test_execution_plan_builder_rejects_stale_input_matrix(self) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            contract, _, contract_sha = self._write_batch2_contract(root)
            graph = root / "graph.json"
            plan = root / "execution-plan.json"
            graph_payload, _ = self._batch2_graph_fixture(root, contract_sha256=contract_sha)
            write_json(graph, graph_payload)
            gate_report = self._write_batch1_gate_report(root, graph_path=graph, graph_payload=graph_payload)
            original_report = json.loads(gate_report.read_text(encoding="utf-8"))
            for mutate in ("graph_sha256", "graph_node_ids", "review_queue", "node_statuses_sha256"):
                mutated = json.loads(json.dumps(original_report))
                if mutate == "graph_sha256":
                    mutated["graph_sha256"] = "bad-graph"
                elif mutate == "graph_node_ids":
                    mutated["graph_node_ids"] = mutated["graph_node_ids"][:-1]
                elif mutate == "review_queue":
                    mutated["review_queue"]["sha256"] = "bad-review-queue"
                else:
                    mutated["node_statuses_sha256"] = "bad-statuses"
                write_json(gate_report, mutated)
                planned = run_script(
                    BUILD_EXECUTION_PLAN,
                    "--contract", str(contract),
                    "--graph", str(graph),
                    "--gate-report", str(gate_report),
                    "--output", str(plan),
                )
                self.assertNotEqual(planned.returncode, 0)
                self.assertIn("gate report", json.loads(planned.stdout)["error"])
            write_json(gate_report, original_report)

